<?php
declare(strict_types=1);namespace HyperfTest\Cases;use App\Service\BillingSchemaService;use Hyperf\DbConnection\Db;use Mockery;use PHPUnit\Framework\TestCase;
final class BillingSchemaServiceTest extends TestCase{protected function tearDown():void{Mockery::close();parent::tearDown();}public function testCreatesSnapshotSettlementAndPermanentAuditTables():void{$db=Mockery::mock(Db::class);$sql=[];$db->shouldReceive('statement')->times(6)->withArgs(function(string$s)use(&$sql){$sql[]=$s;return true;})->andReturnTrue();(new BillingSchemaService($db))->ensureSchema();$all=implode("\n",$sql);foreach(['billing_invoices','billing_items','payment_proofs','commission_configs','supplier_settlements','billing_audit_logs']as$t)self::assertStringContainsString("CREATE TABLE IF NOT EXISTS `{$t}`",$all);foreach($sql as$s)foreach(['created_at','updated_at','deleted_at']as$f)self::assertStringContainsString("`{$f}`",$s);self::assertStringContainsString('unit_price_micros',$all);self::assertStringContainsString('commission_bps',$all);}}
